{"aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "config": {
    "kibana": {
      "hideWarnings": true,
      "renderer": "svg"
    },
    "text": {
      "baseline": "middle",
      "fill": "#343741",
      "font": "Inter UI, -apple-system, BlinkMacSystemFont, Segoe UI, Helvetica, Arial, sans-serif",
      "fontSize": 14
    }
  },
  "data": [
    {
      "format": {
        "property": "aggregations.r.buckets"
      },
      "name": "src",
      "transform": [
        {
          "as": [
            "vb"
          ],
          "fields": [
            "v.buckets"
          ],
          "type": "flatten"
        },
        {
          "as": "rule",
          "expr": "datum.key",
          "type": "formula"
        },
        {
          "as": "value",
          "expr": "datum.vb.key",
          "type": "formula"
        },
        {
          "as": "alerts",
          "expr": "datum.vb.doc_count",
          "type": "formula"
        },
        {
          "as": "desc",
          "expr": "length(datum.vb.d.buckets) ? datum.vb.d.buckets[0].key : ''",
          "type": "formula"
        },
        {
          "as": "level",
          "expr": "datum.l.value",
          "type": "formula"
        }
      ],
      "url": {
        "body": {
          "aggs": {
            "r": {
              "aggs": {
                "l": {
                  "max": {
                    "field": "rule.level"
                  }
                },
                "v": {
                  "aggs": {
                    "d": {
                      "terms": {
                        "field": "rule.description",
                        "size": 1
                      }
                    }
                  },
                  "terms": {
                    "field": "data.jt_ai.agent",
                    "missing": "-",
                    "size": 5
                  }
                }
              },
              "terms": {
                "field": "rule.id",
                "size": 50
              }
            }
          },
          "query": {
            "bool": {
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "query_string": {
                    "analyze_wildcard": true,
                    "query": "rule.id:[133700 TO 133799] AND rule.id:/[0-9]{6}/"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "size": 0
        },
        "index": "wazuh-alerts-*"
      }
    },
    {
      "name": "rows",
      "source": "src",
      "transform": [
        {
          "as": [
            "row0"
          ],
          "ops": [
            "row_number"
          ],
          "sort": {
            "field": {
              "signal": "sortField"
            },
            "order": {
              "signal": "sortDesc ? 'descending' : 'ascending'"
            }
          },
          "type": "window"
        },
        {
          "as": "row",
          "expr": "datum.row0 - 1",
          "type": "formula"
        },
        {
          "expr": "datum.row < floor((height - 38) / 34)",
          "type": "filter"
        }
      ]
    },
    {
      "name": "head",
      "values": [
        {
          "align": "left",
          "i": 0,
          "key": "rule",
          "label": "Rule",
          "num": false,
          "pl": 0,
          "pr": 10,
          "right": false
        },
        {
          "align": "right",
          "i": 1,
          "key": "level",
          "label": "Level",
          "num": true,
          "pl": 12,
          "pr": 10,
          "right": true
        },
        {
          "align": "left",
          "i": 2,
          "key": "value",
          "label": "AI agent",
          "num": false,
          "pl": 12,
          "pr": 10,
          "right": false
        },
        {
          "align": "right",
          "i": 3,
          "key": "alerts",
          "label": "Alerts",
          "num": true,
          "pl": 12,
          "pr": 10,
          "right": true
        },
        {
          "align": "left",
          "i": 4,
          "key": "desc",
          "label": "Description",
          "num": false,
          "pl": 12,
          "pr": 0,
          "right": false
        }
      ]
    },
    {
      "name": "grips",
      "values": [
        {
          "k": 0
        },
        {
          "k": 1
        },
        {
          "k": 2
        },
        {
          "k": 3
        }
      ]
    }
  ],
  "marks": [
    {
      "encode": {
        "update": {
          "align": {
            "field": "align"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#1A1C21"
          },
          "fontWeight": {
            "value": "bold"
          },
          "limit": {
            "signal": "max(10, colE[datum.i] - datum.pl - 8)"
          },
          "text": {
            "signal": "datum.label + (datum.key === sortField ? (sortDesc ? ' ▼' : ' ▲') : '')"
          },
          "tooltip": {
            "value": "Click to sort"
          },
          "x": {
            "signal": "datum.right ? colS[datum.i] + colE[datum.i] - datum.pr : colS[datum.i] + datum.pl"
          },
          "y": {
            "value": 19.0
          }
        }
      },
      "from": {
        "data": "head"
      },
      "name": "jtHead",
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "stroke": {
            "value": "#343741"
          },
          "strokeWidth": {
            "value": 2
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "value": 38
          },
          "y2": {
            "value": 38
          }
        }
      },
      "type": "rule"
    },
    {
      "encode": {
        "hover": {
          "fill": {
            "value": "#F5F7FA"
          },
          "fillOpacity": {
            "value": 1
          }
        },
        "update": {
          "fill": {
            "value": "#FFFFFF"
          },
          "fillOpacity": {
            "value": 0
          },
          "height": {
            "value": 34
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "datum.row * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "rect"
    },
    {
      "encode": {
        "update": {
          "stroke": {
            "value": "#D3DAE6"
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "(datum.row + 1) * 34 + 38"
          },
          "y2": {
            "signal": "(datum.row + 1) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "rule"
    },
    {
      "encode": {
        "update": {
