            "signal": "jtDrag && jtDrag.k === datum.k ? '#006BB4' : '#C6CCD6'"
          },
          "strokeWidth": {
            "signal": "jtDrag && jtDrag.k === datum.k ? 2 : 1"
          },
          "x": {
            "signal": "colS[datum.k + 1]"
          },
          "x2": {
            "signal": "colS[datum.k + 1]"
          },
          "y": {
            "value": 10
          },
          "y2": {
            "value": 28
          }
        }
      },
      "from": {
        "data": "grips"
      },
      "interactive": false,
      "type": "rule"
    },
    {
      "encode": {
        "hover": {
          "fillOpacity": {
            "value": 0.15
          }
        },
        "update": {
          "cursor": {
            "value": "col-resize"
          },
          "fill": {
            "value": "#006BB4"
          },
          "fillOpacity": {
            "value": 0
          },
          "height": {
            "value": 38
          },
          "tooltip": {
            "value": "Drag to change the column width"
          },
          "width": {
            "value": 10
          },
          "x": {
            "signal": "colS[datum.k + 1] - 5"
          },
          "y": {
            "value": 0
          }
        }
      },
      "from": {
