        "update": {
          "align": {
            "value": "left"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#006BB4"
          },
          "limit": {
            "signal": "max(10, colE[2] - 20)"
          },
          "text": {
            "field": "value"
          },
          "tooltip": {
            "signal": "'Click to filter' + ': ' + datum.value"
